// Generated by app-probing. Deleted after the run. Never commit.
import { type Page, type Request } from '@playwright/test';

// `test` from the file that declares the fixture, not from '@playwright/test'.
import { test } from '<the fixture file>';

/**
 * Tracks the app's requests from the start of the body, including the ones the interaction sends, and returns
 * settle(): a bounded wait until no app request is in flight and none started or ended for quietMs, so the
 * evidence describes a settled screen, not a half-loaded one. Not an assertion: it never fails, it only stops
 * waiting.
 */
function trackTraffic(page: Page, isApp: (url: string) => boolean) {
  const pending = new Set<Request>();
  let last = Date.now();
  page.on('request', (request) => {
    if (!isApp(request.url())) return;
    pending.add(request);
    last = Date.now();
  });
  const done = (request: Request) => {
    if (pending.delete(request)) last = Date.now();
  };
  page.on('requestfinished', done);
  page.on('requestfailed', done);

  return async function settle({ quietMs = 700, timeoutMs = 8000 } = {}): Promise<number> {
    const start = Date.now();
    while (Date.now() - start < timeoutMs && (pending.size > 0 || Date.now() - last < quietMs)) {
      await page.waitForTimeout(100);
    }
    return Date.now() - start;
  };
}

test('probe: <what the user asked for>', async ({ page /* , <fixture>: { … } */ }, testInfo) => {
  // --headed only: uncomment, or the test timeout closes the browser while you are in it.
  // test.setTimeout(0);

  const consoleErrors: string[] = [];
  const failedRequests: string[] = [];

  // The app's own traffic is the signal; analytics beacons are not.
  // Add the API's origin when the app calls one on another host. Leave out a request that stays open for good
  // (long polling, server-sent events), or settle() always runs to its cap.
  const appOrigins = [new URL(testInfo.project.use.baseURL ?? page.url()).origin];
  const isApp = (url: string) => appOrigins.some((origin) => url.startsWith(origin));
  const settle = trackTraffic(page, isApp);

  page.on('console', (message) => {
    if (message.type() === 'error') consoleErrors.push(message.text());
  });
  page.on('requestfailed', (request) => {
    // ERR_ABORTED is a navigation or the teardown cancelling a request, not a failure.
    if (request.failure()?.errorText.includes('ERR_ABORTED') || !isApp(request.url())) return;
    failedRequests.push(`${request.method()} ${request.url()} — ${request.failure()?.errorText}`);
  });
  page.on('response', (response) => {
    if (response.status() >= 400 && isApp(response.url())) {
      failedRequests.push(`${response.status()} ${response.request().method()} ${response.url()}`);
    }
  });

  // Interaction: Page Object methods only, in the order the request describes.
  // await <pages>.<page>.<method>(…);

  const settledInMs = await settle();

  const idAttribute = testInfo.project.use.testIdAttribute ?? 'data-testid';
  const testIds = (
    await page
      .locator(`[${idAttribute}]`)
      .evaluateAll((elements, name) => elements.map((element) => element.getAttribute(name)), idAttribute)
  ).filter(Boolean);

  const screenshot = testInfo.outputPath('probe.png');
  await page.screenshot({ fullPage: true, path: screenshot });

  console.log(
    'PROBE ' +
      JSON.stringify(
        {
          url: page.url(),
          user: undefined, // the credentials the fixture gives, if any
          testIds,
          consoleErrors,
          failedRequests,
          settledInMs,
          screenshot,
        },
        null,
        2,
      ),
  );

  // --headed only: hold the browser open for the Playwright Inspector.
  // await page.pause();
});
